const fs = require('fs');
const crypto = require('crypto');
try {
  const data = fs.readFileSync('E:\\tqrepo\\body_candidate.txt', 'utf8');
  const sha = crypto.createHash('sha256').update(data).digest('hex');
  console.log(sha);
} catch(e) {
  console.error(e.message);
}

